def F(x):
    x = np.nan_to_num(x, nan=0.0, posinf=1e30, neginf=-1e30)
    t0 = np.clip(-1000.0 * x, -500.0, 500.0)
    t1 = np.clip(1000.0 * (x - 1.0), -500.0, 500.0)
    val = 255.0 * np.exp(-np.exp(t0)) * (np.maximum(np.abs(x), 1e-15) ** np.exp(-np.exp(t1)))
    return np.floor(np.clip(val + 1e-9, 0.0, 255.0)).astype(np.uint8)


def render():
    m = np.arange(1, W + 1, dtype=np.float64)
    n = np.arange(1, H + 1, dtype=np.float64)
    x_grid, y_grid = ((m[None, :] - M0) / S), ((N0 - n[:, None]) / S)
    out = np.zeros((H, W, 3), dtype=np.uint8)

    u_arr = np.array([t[0] for t in TRIG_TERMS], dtype=np.float64)
    v_arr = np.array([t[1] for t in TRIG_TERMS], dtype=np.float64)
    c0_arr = np.array([t[2] for t in TRIG_TERMS], dtype=np.float64)
    c1_arr = np.array([t[3] for t in TRIG_TERMS], dtype=np.float64)
    c2_arr = np.array([t[4] for t in TRIG_TERMS], dtype=np.float64)

    try:  # fast path: the cosine series is exactly an inverse 2-D DCT
        from scipy.fft import idctn
        au = np.where(u_arr == 0, np.sqrt(1.0 / H), np.sqrt(2.0 / H))
        av = np.where(v_arr == 0, np.sqrt(1.0 / W), np.sqrt(2.0 / W))
        norm = au * av
        iu, iv = u_arr.astype(int), v_arr.astype(int)
        def cosine_series(s):
            spec = np.zeros((H, W))
            np.add.at(spec, (iu, iv), (c0_arr + c1_arr * s + c2_arr * s ** 2) / norm)
            return idctn(spec, type=2, norm="ortho")
    except ImportError:  # pure NumPy fallback (slower for many terms)
        cos_y = np.cos(np.pi * (n[:, None] - 0.5) * u_arr[None, :] / H)
        cos_x = np.cos(np.pi * v_arr[:, None] * (m[None, :] - 0.5) / W)
        def cosine_series(s):
            return (cos_y * (c0_arr + c1_arr * s + c2_arr * s ** 2)[None, :]) @ cos_x

    for s in range(3):
        prod = np.ones((H, W), dtype=np.float64)
        for (x0, y0, th, a, b, k, c0, c1, c2) in PRIMITIVES:
            ct, st = np.cos(th), np.sin(th)
            u = ((x_grid - x0) * ct + (y_grid - y0) * st) / a
            v = (-(x_grid - x0) * st + (y_grid - y0) * ct) / b
            A_p = np.exp(-np.exp(np.clip(k * (u ** 2 + v ** 2 - 1.0), -40.0, 40.0)))
            prod *= (1.0 - (c0 + c1 * s + c2 * (s ** 2)) * A_p)
        C_s = cosine_series(s) if len(TRIG_TERMS) else 0.0
        out[:, :, s] = F((1.0 - prod) + C_s)

    Image.fromarray(out).save("reconstructed_from_equation.png")
    print("Saved reconstructed_from_equation.png")


if __name__ == "__main__":
    render()
